using System;using System.IO;using System.Linq;using System.Windows;using System.Windows.Controls;
namespace Touchfish {
public partial class PanelWindow {
 public void PreviewBlackrockScope(string folder){previewRun=true;Directory.CreateDirectory(folder);int before=checks;if(VerificationRun.Visual)VerifyBlackrockUi(folder);if(VerificationRun.Network)VerifyBlackrockTcp();File.WriteAllText(Path.Combine(folder,"blackrock-verification.txt"),"PASS: "+(checks-before)+" checks; WPF rendering and loopback TCP, not human mouse or two-machine testing.");}
 void VerifyBlackrockUi(string folder){
  ApplyTheme(true,true);ApplyMode(false);draft=new DeckDocument{PoolId=BlackrockRules.SetId,ClassId="ROGUE"};showAllCards.IsChecked=true;versionPicker.SelectedItem=versionPicker.Items.OfType<Choice>().Single(c=>c.Key==BlackrockRules.SetId);searchBox.Text="";ShowPage("deck");RefreshDeck();
  Check(filteredCards.Count==31&&filteredCards.All(matchRules.Supports),"Version filter exposes all 31 playable Blackrock cards");foreach(var c in filteredCards.ToArray()){ShowDeckCard(c);Check(cardInfo.Text.Contains("可对战")&&!cardInfo.Text.Contains("暂不可用"),"Playable details: "+c.Id);}
  searchBox.Text="夜幕奇袭";Check(filteredCards.Count==1&&filteredCards[0].Id=="BRM_007","Gang Up search");ShowDeckCard(filteredCards[0]);Render(Path.Combine(folder,"blackrock-builder-normal.png"));ApplyMode(true);Render(Path.Combine(folder,"blackrock-builder-minimal.png"));Check(Width==392&&Height==300,"Minimal builder retains dimensions");ApplyMode(false);searchBox.Text="";versionPicker.SelectedIndex=0;
  localTest=true;match=MatchFixture();match.CardPoolId=BlackrockRules.SetId;match.Players[0].ClassId="DRUID";matchViewSeat=0;awaitHandoff=false;foreach(var p in match.Players){p.Hand.Clear();p.Board.Clear();}ShowPage("match");int hand=NaxxUiHand(match,"BRM_010");BeginCard(hand);ClickEmptySlot(0,0);Check(ChoicePending(),"Flame Druid opens choose-one workflow");Render(Path.Combine(folder,"blackrock-choose.png"));SelectChoice("health");Check(match.Players[0].Board.Single().CardId=="BRM_010t2","WPF choose-one transforms to correct beast");
  match.Players[0].Board.Clear();hand=NaxxUiHand(match,"BRM_029");match.Players[0].Mana=10;BeginCard(hand);ClickEmptySlot(0,0);Check(pending!="play"&&match.Players[0].Board.Single().CardId=="BRM_029","Rend without dragon resolves without target prompt");
  match.Players[0].Board.Clear();match.Summon(1,"GVG_110");NaxxUiHand(match,"BRM_025");hand=NaxxUiHand(match,"BRM_029");match.Players[0].Mana=10;BeginCard(hand);ClickEmptySlot(0,0);Check(pending=="play"&&match.Players[0].Board.Count==0,"Rend holding dragon waits for legendary target");ClickMatchTarget(new MatchTarget(1,match.Players[1].Board.Single().Id));Check(!match.Players[1].Board.Any(),"Legendary target battlecry resolves through UI");
  match.Players[0].Board.Clear();for(int i=0;i<6;i++)match.Summon(0,"GVG_110t");match.Summon(0,"FP1_031");RenderMatch();Render(Path.Combine(folder,"blackrock-bombs-normal.png"));Check(Width==548&&Height==474&&match.Players[0].Board.Count==7,"Seven bomb-combo slots fit fixed office window");ApplyMode(true);RenderMatch();Render(Path.Combine(folder,"blackrock-bombs-minimal.png"));Check(matchEffectsCanvas.Visibility==Visibility.Collapsed,"Minimal remains free of effects");ApplyMode(false);localTest=false;ClearPending();match=null;
 }
 void VerifyBlackrockTcp(){
  LeaveLan();ApplyTheme(true,true);ApplyMode(false);SetEffectsLevel(EffectLevel.Off);var guest=new PanelWindow(true){ShowInTaskbar=false,Opacity=0};guest.Show();guest.ApplyMode(false);guest.SetEffectsLevel(EffectLevel.Off);
  try{lanPort.Text=FreeLanPort().ToString();lanModePicker.SelectedIndex=0;lanClass.SelectedItem=Classes.First(c=>c.Key=="MAGE");lanDeck.SelectedIndex=0;BeginLan(true);guest.lanModePicker.SelectedIndex=0;guest.lanClass.SelectedItem=Classes.First(c=>c.Key=="MAGE");guest.lanDeck.SelectedIndex=0;guest.lanAddress.Text="127.0.0.1:"+lanPort.Text;guest.BeginLan(false);PumpLan(()=>lanReady&&guest.lanReady,"Blackrock peers connect");DoMatch("mulligan",selectedIds:new int[0]);PumpLan(()=>guest.match.Players[0].MulliganDone,"Host mulligan");guest.DoMatch("mulligan",selectedIds:new int[0]);PumpLan(()=>match.MulliganComplete&&!guest.lanWaiting,"Both mulligans complete");var g=lanAuthority.Game;Check(g.CardPoolId==BlackrockRules.SetId&&guest.match.CardPoolId==BlackrockRules.SetId,"Archived decks promote into same Blackrock pool on both peers");
   for(int seat=0;seat<2;seat++){
    GvgTcpReset(seat);g.DeathsThisTurn=0;g.Players[seat].ClassId="ROGUE";var bomb=g.Summon(seat,"GVG_110t");g.Players[seat].Deck.Clear();int gang=NaxxUiHand(g,"BRM_007",seat);PublishLan();var actor=seat==0?this:guest;PumpLan(()=>actor.match.Players[seat].Hand.Any(h=>h.Id==gang),"Gang Up hand arrives");actor.DoMatch("play",gang,new MatchTarget(seat,bomb.Id));PumpLan(()=>guest.match.Players[seat].Deck.Count==3&&!actor.lanWaiting,"Three shuffled copies reach both deck counts");Check(LanProtocol.View(g,1-seat,"brm-privacy",1).Players[seat].Hand.Length==0,"Gang Up does not expose private hand");
    GvgTcpReset(seat);g.DeathsThisTurn=0;g.Players[seat].ClassId="PALADIN";int consort=NaxxUiHand(g,"BRM_018",seat);PublishLan();PumpLan(()=>actor.match.Players[seat].Hand.Any(h=>h.Id==consort),"Consort arrives");actor.DoMatch("play",consort,null,0);PumpLan(()=>guest.match.Players[seat].NextDragonDiscount==2&&!actor.lanWaiting,"Dragon discount reaches both peers");
    var dead=g.Summon(1-seat,"VAN_CS2_231");g.Damage(new MatchTarget(dead.Owner,dead.Id),1);g.Cleanup();int dragon=NaxxUiHand(g,"BRM_025",seat);PublishLan();PumpLan(()=>actor.match.Players[seat].Hand.Any(h=>h.Id==dragon)&&actor.match.DeathsThisTurn==1,"Public death counter and private hand arrive together");Check(actor.match.HandCost(seat,actor.match.Players[seat].Hand.Single(h=>h.Id==dragon))==3,"Client displays authority's death and dragon discounts");
    GvgTcpReset(seat);g.DeathsThisTurn=0;var boss=g.Summon(seat,"BRM_027");g.Damage(new MatchTarget(seat,boss.Id),7);g.Cleanup();PublishLan();PumpLan(()=>guest.match.Players[seat].HeroFormId==BlackrockRules.Ragnaros,"Deathrattle hero replacement synchronizes");g.Players[1-seat].Board.Clear();g.Players[seat].Mana=10;PublishLan();actor.DoMatch("power");PumpLan(()=>guest.match.Players[1-seat].Health==22&&!actor.lanWaiting,"Ragnaros power executes authoritatively from either seat");
   }
  }finally{guest.LeaveLan();guest.Close();LeaveLan();}
 }
}
}
